package com.example.appsaudebackend.Modules.Medico.Service;
import com.example.appsaudebackend.Modules.Medico.Dto.Request.AtualizarMedicoRequestDto; import com.example.appsaudebackend.Modules.Medico.Dto.Response.MedicoPerfilResponseDto; import com.example.appsaudebackend.Modules.Medico.Persistencia.*; import com.example.appsaudebackend.Shared.Exception.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class MedicoPerfilService{ private final MedicoRepository repo;
@Transactional(readOnly=true) public MedicoPerfilResponseDto obter(String cpf){return toResponse(find(cpf));}
@Transactional public MedicoPerfilResponseDto atualizar(String cpf,AtualizarMedicoRequestDto dto){MedicoModel m=find(cpf);repo.findByEmail(dto.email()).filter(o->!o.getId().equals(m.getId())).ifPresent(o->{throw new ConflitoException("E-mail já cadastrado.");});m.setNome(dto.nome());m.setEmail(dto.email());m.setTelefone(dto.telefone());return toResponse(repo.save(m));}
private MedicoModel find(String cpf){return repo.findByUsuarioAuthCpf(cpf).orElseThrow(()->new RecursoNaoEncontradoException("Médico não encontrado."));}
private MedicoPerfilResponseDto toResponse(MedicoModel m){return new MedicoPerfilResponseDto(m.getNome(),m.getEmail(),m.getTelefone(),m.getCrm(),m.getEspecialidade());}}